#![cfg(feature = "usb")]
//! Runs programs generated by `reef_infer::codegen` on an Edge TPU and checks
//! every output byte against the host reference.

use std::sync::Arc;

use reef_infer::codegen::Quant;
use reef_infer::codegen::elementwise::{self, Requant, SIZE};
use reef_infer::codegen::fc::Fc;
use reef_infer::runner::Device;

fn bytes(seed: &mut u64, n: usize) -> Vec<u8> {
    (0..n)
        .map(|_| {
            *seed ^= *seed << 13;
            *seed ^= *seed >> 7;
            *seed ^= *seed << 17;
            (*seed >> 32) as u8
        })
        .collect()
}

#[tokio::test]
async fn generated_programs_on_tpu() {
    let mut dev = Device::open().await.expect("failed to open device");
    let mut seed = 0x9e3779b97f4a7c15u64;

    // Element-wise requantization, including parameters the compiler would
    // never emit (negative multiplier, nonzero out_zp, asymmetric clamp).
    let q = Quant {
        scale: 0.05,
        zero_point: 128,
    };
    for rq in [
        Requant::from_quant(
            q,
            Quant {
                scale: 0.025,
                zero_point: 0,
            },
            true,
        ),
        Requant {
            in_zp: 128,
            mult: -1.0,
            clamp_min: -128.0,
            clamp_max: 127.0,
            out_zp: 128,
        },
        Requant {
            in_zp: 100,
            mult: 2.5,
            clamp_min: -10.0,
            clamp_max: 40.7,
            out_zp: 50,
        },
    ] {
        let model = Arc::new(elementwise::build(&rq, q, q, true).unwrap().into_model());
        let x = bytes(&mut seed, SIZE);
        let loaded = dev.load_params(model).await.unwrap();
        let got = dev.run_inference(&loaded, x.clone()).await.unwrap();
        let want: Vec<u8> = x.iter().map(|&v| rq.apply(v)).collect();
        assert!(got == want, "{rq:?}");
    }

    // Fully connected layers with random weights.
    for (k, n, relu) in [(64, 64, false), (8, 16, true), (40, 48, false)] {
        let w = bytes(&mut seed, n * k);
        let fc = Fc {
            k,
            n,
            weights: w.iter().map(|&b| b as i8).collect(),
            w_scale: (0..n).map(|i| 0.003 + 0.0002 * i as f32).collect(),
            bias: (0..n).map(|i| 250 * i as i32 - 5000).collect(),
            input: Quant {
                scale: 0.03,
                zero_point: 120,
            },
            output: Quant {
                scale: 0.3,
                zero_point: 130,
            },
            relu,
        };
        let loaded = dev
            .load_params(Arc::new(fc.build().unwrap()))
            .await
            .unwrap();
        for _ in 0..4 {
            let x = bytes(&mut seed, k);
            let got = dev.run_inference(&loaded, x.clone()).await.unwrap();
            assert_eq!(got, fc.reference(&x), "fc K={k} N={n} relu={relu}");
        }
    }
}
